preConditionHook:
// EL: ph = highest(h, lookback)[1]; pl = lowest(l, lookback)[1] -- the block
// of lookback bars ending one bar ago, i.e. bars 1..lookback.
// EL highest/lowest bottom out in Extremes(), which is EL SOURCE: seeded at
// the first bar of the window, scanning the rest with a strict,
// tolerance-carrying comparison. So the loop below seeds first and uses
// el_gt/el_lt for the scan (see Breakout and CloseAbovePriorHighestHigh).
ph = high[1];
pl = low[1];
for (int i = 2; i <= (int)lookback; ++i) {
    if (el_gt(high[i], ph)) ph = high[i];
    if (el_lt(low[i], pl)) pl = low[i];
}
// EL: ov = minlist(h, ph) - maxlist(l, pl). Both operands of each selection
// are traded prices (a bar extreme against a window extreme).
// MinList/MaxList are ACCEPTED for tick-grid PRICE operands only
// (EL_FEATURES.md): these operands are bar extremes, so they differ by
// exactly 0 or by at least one tick -- 1e9-1e11x the relational tolerance --
// and whichever comparison the reserved word carries cannot matter. The
// plain ternary stand-in is therefore exact, the same arrangement
// TwoBarRangePosition and AtrProfitTarget use. (<algorithm> is not among
// the emitted includes, so no std::min/std::max.)
ov = (high[0] < ph ? high[0] : ph) - (low[0] > pl ? low[0] : pl);
